import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        int k = sc.nextInt();

        List<Integer> digits = new ArrayList<>();
        while (n > 0) {
            digits.add((int)(n % k));
            n /= k;
        }

        long MOD = 1000000007;
        int size = k + 1;
        long[][] mat = new long[size][size];

        for (int j = 0; j <= k; ++j) {
            mat[0][j] = 1;
            mat[j][j] = 1;
        }

        // Matrix multiplication
        long[][] mat_mult(long[][] A, long[][] B) {
            long[][] res = new long[size][size];
            for (int i = 0; i < size; ++i) {
                for (int j = 0; j < size; ++j) {
                    long sum = 0;
                    for (int l = 0; l < size; ++l) {
                        sum += A[i][l] * B[l][j];
                    }
                    res[i][j] = sum % MOD;
                }
            }
            return res;
        }

        // Matrix exponentiation
        long[][] mat_pow(long[][] base, long exp) {
            long[][] result = new long[size][size];
            for (int i = 0; i < size; ++i) {
                result[i][i] = 1;
            }
            while (exp > 0) {
                if ((exp & 1) == 1) {
                    result = mat_mult(result, base);
                }
                base = mat_mult(base, base);
                exp >>= 1;
            }
            return result;
        }

        long[][] A = new long[size][size];
        for (int i = 0; i < size; ++i) {
            System.arraycopy(mat[i], 0, A[i], 0, size);
        }

        long sum_mod = 0;
        for (int i = digits.size() - 1; i >= 0; --i) {
            int digit = digits.get(i);
            for (int j = 0; j < digit; ++j) {
                long[][] temp = mat_pow(A, (j + sum_mod) % k);
                for (int x = 0; x < size; ++x) {
                    for (int y = 0; y < size; ++y) {
                        mat[x][y] = (mat[x][y] + temp[x][y]) % MOD;
                    }
                }
            }
            sum_mod = (sum_mod + digit) % k;
        }

        long total_answer = 0;
        for (int i = 0; i <= k; ++i) {
            total_answer = (total_answer + mat[i][k]) % MOD;
        }

        System.out.println(total_answer);
        sc.close();
    }
}
